#!/usr/bin/env python3
"""
scaffold_frontend.py

Generates the complete "front-end/" static SPA project structure and writes
every file's contents in one run. This is the updated front-end that talks
to the FastAPI backend (Google OAuth + local SQLite sessions, no AWS
Cognito, no Lambda Function URL) via a small set of ES modules instead of
one monolithic app.js.

Usage:
    python scaffold_frontend.py                  # creates ./front-end
    python scaffold_frontend.py /path/to/parent   # creates /path/to/parent/front-end
    python scaffold_frontend.py --force           # overwrite existing files

The resulting tree:

  front-end/
    config.js                 Runtime config template (BACKEND_URL, OAuth client IDs)
    Dockerfile                nginx:alpine image, listens on 3000, SPA fallback
    nginx.conf                Server block used by the Dockerfile
    js/
      api.js                  Fetch wrapper: base URL, session header, error normalization
      auth.js                 Google OAuth (server-redirect flow) + session state
      auth-ui.js               DOM wiring for signed-in/out header state
      pkce.js                  PKCE helpers (used only by the GitLab connect flow)
      integrations.js          GitHub/GitLab connect, callback, disconnect logic
      integrations-ui.js       DOM wiring for the integrations modal
      stream.js                NDJSON + SSE parser for /v1/chat/completions
      render.js                Chat bubble / progress / confirmation DOM rendering
      chat.js                  send() and pending-action resolution logic
      attachments.js           File attach, drag & drop, size validation
      theme.js                 Dark/light theme toggle
      main.js                  App bootstrap: wires DOM events, dispatches routes

Note: index.html is NOT regenerated by this script since it is largely
static markup already owned by the project; wire it to these modules with:

    <script type="module" src="/config.js"></script>
    <script type="module" src="/js/main.js"></script>

and ensure the element IDs referenced throughout js/*.js exist in the DOM
(chat, input, send-btn, file-input, file-chips, drop-overlay, empty-state,
typing-indicator, auth-signed-out, auth-signed-in, user-email,
google-login-btn, logout-btn, integrations-modal, integrations-open-btn,
integrations-close-btn, integrations-dot, github-status-text,
github-connect-btn, github-auth-btn, github-auth-btn-label,
gitlab-status-text, gitlab-connect-btn, gitlab-auth-btn,
gitlab-auth-btn-label, theme-toggle-btn, theme-icon).
"""
import argparse
from pathlib import Path

FILES = {
  "config.js": "// front-end/config.js\n//\n// Runtime configuration for the Coding Agent front-end.\n// These placeholders are substituted at deploy/container-build time (see\n// docker-entrypoint substitution in Dockerfile, or your CI \"inject config\"\n// step) \u2014 never hardcode real values here; this file is checked into git\n// as a template only.\n//\n// BACKEND_URL must point at the FastAPI service (see back-end/main.py).\n// There is no Cognito, no Lambda Function URL, and no CloudFormation output\n// to inject anymore \u2014 this is a plain HTTP(S) origin for the FastAPI app,\n// e.g. \"https://api.example.com\" or \"http://localhost:\" in development.\nwindow.APP_CONFIG = {\n  BACKEND_URL: \"__BACKEND_URL__\",\n  GITHUB_OAUTH_CLIENT_ID: \"__GITHUB_OAUTH_CLIENT_ID__\",\n  GITLAB_OAUTH_CLIENT_ID: \"__GITLAB_OAUTH_CLIENT_ID__\",\n};\n",
  "js/api.js": "// front-end/js/api.js\n//\n// Thin fetch wrapper for the FastAPI back-end (see back-end/main.py).\n// Centralizes the base URL, session-token header injection, and error\n// normalization so every other module calls one consistent function\n// instead of hand-rolling fetch() + header objects everywhere.\n//\n// Session model: the back-end issues an opaque session token from\n// GET /v1/auth/google/callback (see auth.js) and also sets it as an\n// HttpOnly `agent_session` cookie. We store a copy in localStorage so we\n// can send it as `Authorization: Bearer <token>` explicitly \u2014 this keeps\n// the app working even when the API and front-end are served from\n// different origins/ports, where a cross-site cookie could be blocked or\n// stripped by the browser depending on SameSite/Secure configuration.\n\nconst BACKEND_URL = window.APP_CONFIG.BACKEND_URL;\nconst SESSION_STORAGE_KEY = \"agent_session_token\";\n\nexport class ApiError extends Error {\n  constructor(message, status) {\n    super(message);\n    this.name = \"ApiError\";\n    this.status = status;\n  }\n}\n\nexport function getSessionToken() {\n  return localStorage.getItem(SESSION_STORAGE_KEY);\n}\n\nexport function setSessionToken(token) {\n  if (token) {\n    localStorage.setItem(SESSION_STORAGE_KEY, token);\n  } else {\n    localStorage.removeItem(SESSION_STORAGE_KEY);\n  }\n}\n\nfunction authHeaders() {\n  const token = getSessionToken();\n  return token ? { Authorization: `Bearer ${token}` } : {};\n}\n\n/**\n * Performs a JSON request against the backend and returns the parsed body.\n * Throws ApiError on non-2xx responses.\n */\nexport async function apiFetch(path, { method = \"GET\", body, headers = {} } = {}) {\n  const response = await fetch(`${BACKEND_URL}${path}`, {\n    method,\n    credentials: \"include\",\n    headers: {\n      ...(body ? { \"Content-Type\": \"application/json\" } : {}),\n      ...authHeaders(),\n      ...headers,\n    },\n    body: body ? JSON.stringify(body) : undefined,\n  });\n\n  let payload = null;\n  try {\n    payload = await response.json();\n  } catch {\n    // Some endpoints (e.g. streaming) never reach here; non-JSON bodies\n    // on error responses are treated as an empty payload.\n  }\n\n  if (!response.ok) {\n    const message = payload?.detail || payload?.error || `Request failed (${response.status})`;\n    throw new ApiError(message, response.status);\n  }\n\n  return payload;\n}\n\n/**\n * Opens a raw streaming POST request (used for /v1/chat/completions) and\n * returns the fetch Response so the caller can read response.body directly.\n * Not routed through apiFetch() because the response body is a stream of\n * NDJSON + SSE frames, not a single JSON document \u2014 see stream.js.\n */\nexport async function apiStream(path, body) {\n  const response = await fetch(`${BACKEND_URL}${path}`, {\n    method: \"POST\",\n    credentials: \"include\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n      ...authHeaders(),\n    },\n    body: JSON.stringify(body),\n  });\n\n  if (!response.ok) {\n    let detail = `backend returned ${response.status}`;\n    try {\n      const errorBody = await response.json();\n      detail = errorBody?.detail || errorBody?.message || detail;\n    } catch {\n      // Ignore unparsable error bodies; fall back to the generic message.\n    }\n    throw new ApiError(detail, response.status);\n  }\n\n  return response;\n}\n",
  "js/auth.js": "// front-end/js/auth.js\n//\n// Application login, replacing the old AWS Cognito Hosted UI + PKCE flow.\n//\n// The FastAPI backend (see back-end/app/services/google_oauth_service.py)\n// now owns the entire Google OAuth + PKCE exchange server-side:\n//\n//   1. The browser navigates (full page load, NOT fetch) to\n//      GET {BACKEND_URL}/v1/auth/google/login.\n//   2. The backend redirects to Google, and Google redirects back to the\n//      backend's own callback endpoint\n//      (GET {BACKEND_URL}/v1/auth/google/callback), never to this front-end\n//      directly. The backend validates everything (state, PKCE, ID token)\n//      and returns a JSON body: {authenticated, user, access_token, ...}.\n//   3. Because that callback response is JSON rendered at the backend's\n//      origin (not a redirect back to the SPA), the recommended integration\n//      is to make the backend's callback endpoint itself redirect to\n//      \"{FRONTEND_ORIGIN}/auth/complete#token=<access_token>\" after success.\n//      This module's completeLoginFromUrlFragment() picks that token up.\n//\n// If your deployment instead keeps the backend callback as a same-origin\n// path behind a reverse proxy (e.g. \"/api/v1/auth/google/callback\" fronted\n// by the same nginx serving this SPA), you can skip the fragment-redirect\n// step entirely and have the backend set the agent_session cookie only;\n// requests will authenticate via that cookie automatically since apiFetch()\n// always sends credentials: \"include\". In that setup access_token handling\n// below becomes optional and localStorage is used purely as a convenience\n// for the Authorization header case documented in api.js.\n\nimport { setSessionToken, apiFetch, ApiError } from \"./api.js\";\n\nconst BACKEND_URL = window.APP_CONFIG.BACKEND_URL;\n\nexport function isSignedIn() {\n  return Boolean(localStorage.getItem(\"agent_session_token\") || document.cookie.includes(\"agent_session=\"));\n}\n\nexport function getCachedUser() {\n  const raw = localStorage.getItem(\"agent_user\");\n  if (!raw) return null;\n  try {\n    return JSON.parse(raw);\n  } catch {\n    return null;\n  }\n}\n\nfunction cacheUser(user) {\n  if (user) {\n    localStorage.setItem(\"agent_user\", JSON.stringify(user));\n  } else {\n    localStorage.removeItem(\"agent_user\");\n  }\n}\n\n/** Starts the Google login flow with a full-page redirect to the backend. */\nexport function loginWithGoogle() {\n  window.location.href = `${BACKEND_URL}/v1/auth/google/login`;\n}\n\n/**\n * Call once on app boot. If the URL contains \"#token=...&...\" (the fragment\n * the backend's OAuth callback redirects the browser to on success), stores\n * the session token, cleans the URL, and fetches the current user profile.\n */\nexport async function completeLoginFromUrlFragment() {\n  const fragment = new URLSearchParams(window.location.hash.replace(/^#/, \"\"));\n  const token = fragment.get(\"token\");\n  if (!token) return false;\n\n  setSessionToken(token);\n  window.history.replaceState({}, \"\", window.location.pathname);\n\n  await refreshCurrentUser();\n  return true;\n}\n\n/** Fetches /v1/auth/me and updates the cached user profile. */\nexport async function refreshCurrentUser() {\n  try {\n    const data = await apiFetch(\"/v1/auth/me\");\n    cacheUser(data.user);\n    return data.user;\n  } catch (err) {\n    if (err instanceof ApiError && err.status === 401) {\n      setSessionToken(null);\n      cacheUser(null);\n    }\n    return null;\n  }\n}\n\n/** Signs the user out both locally and on the server. */\nexport async function logout() {\n  try {\n    await apiFetch(\"/v1/auth/logout\", { method: \"POST\" });\n  } catch {\n    // Best-effort: still clear local state even if the network call fails.\n  } finally {\n    setSessionToken(null);\n    cacheUser(null);\n  }\n}\n",
  "js/pkce.js": "// front-end/js/pkce.js\n//\n// Shared PKCE (Proof Key for Code Exchange, RFC 7636) helpers, used only by\n// the GitLab \"public client\" connect flow (integrations.js). Google login\n// no longer needs this in the browser \u2014 the backend performs PKCE itself\n// against Google (see auth.js) \u2014 but GitLab's browser-only, secretless\n// OAuth app still requires it here.\n\nfunction base64Url(buffer) {\n  return btoa(String.fromCharCode(...new Uint8Array(buffer)))\n    .replace(/\\+/g, \"-\")\n    .replace(/\\//g, \"_\")\n    .replace(/=+$/, \"\");\n}\n\nexport function generateRandomToken() {\n  const array = new Uint8Array(32);\n  crypto.getRandomValues(array);\n  return base64Url(array);\n}\n\nexport async function generateCodeChallenge(verifier) {\n  const digest = await crypto.subtle.digest(\"SHA-256\", new TextEncoder().encode(verifier));\n  return base64Url(digest);\n}\n",
  "js/integrations.js": "// front-end/js/integrations.js\n//\n// GitHub and GitLab repository-access integrations.\n//\n// GitHub: OAuth App \"user-to-server\" flow. GitHub's token exchange requires\n// a client secret, so this module only performs the browser-side authorize\n// redirect. The actual code-for-token exchange happens server-side via\n// POST {BACKEND_URL}/v1/actions with {\"action\": \"github_oauth_callback\"}\n// (see back-end/app/services/github_oauth_service.py and\n// back-end/app/api/actions.py). The resulting token is stored server-side\n// in SQLite (user_integrations table) and is injected automatically for\n// every github_* tool call this user's session makes \u2014 see\n// app/tools/dispatch.py's call_repo_tool().\n//\n// GitLab: registered as a \"public\"/native OAuth application, enabling a\n// full Authorization Code + PKCE exchange directly from the browser without\n// a client secret. Unlike GitHub, this token is NEVER sent to the backend\n// to be stored \u2014 it lives only in this browser's localStorage and is\n// attached to a single /v1/actions request body (as gitlab_token) only at\n// the moment a gitlab_* tool call needs approving (see chat.js). The\n// backend uses it for that one call and never persists it.\n\nimport { apiFetch, ApiError } from \"./api.js\";\nimport { generateRandomToken, generateCodeChallenge } from \"./pkce.js\";\n\nconst GITHUB_CLIENT_ID = window.APP_CONFIG.GITHUB_OAUTH_CLIENT_ID;\nconst GITHUB_REDIRECT_URI = `${window.location.origin}/callback/github`;\nconst GITHUB_SCOPES = \"repo read:user\";\n\nconst GITLAB_CLIENT_ID = window.APP_CONFIG.GITLAB_OAUTH_CLIENT_ID;\nconst GITLAB_OAUTH_DOMAIN = \"https://gitlab.com\";\nconst GITLAB_REDIRECT_URI = `${window.location.origin}/callback/gitlab`;\nconst GITLAB_SCOPES = \"api read_repository write_repository\";\n\n// ---------------------------------------------------------------------\n// GitHub\n// ---------------------------------------------------------------------\n\nexport function isGitHubConnected() {\n  return localStorage.getItem(\"github_connected\") === \"true\";\n}\n\nexport function getGitHubUsername() {\n  return localStorage.getItem(\"github_username\") || \"\";\n}\n\nexport function connectGitHub() {\n  const state = generateRandomToken();\n  sessionStorage.setItem(\"github_oauth_state\", state);\n  const params = new URLSearchParams({\n    client_id: GITHUB_CLIENT_ID,\n    redirect_uri: GITHUB_REDIRECT_URI,\n    scope: GITHUB_SCOPES,\n    state,\n    allow_signup: \"false\",\n  });\n  window.location.href = `https://github.com/login/oauth/authorize?${params}`;\n}\n\n/**\n * Call on GET /callback/github. Returns {ok, message} describing the\n * outcome so the caller (main.js) can render it in the chat transcript.\n */\nexport async function handleGitHubCallback() {\n  const url = new URL(window.location.href);\n  const code = url.searchParams.get(\"code\");\n  const state = url.searchParams.get(\"state\");\n  const expected = sessionStorage.getItem(\"github_oauth_state\");\n  sessionStorage.removeItem(\"github_oauth_state\");\n  window.history.replaceState({}, \"\", \"/\");\n\n  if (!code) return null;\n  if (!state || state !== expected) {\n    return { ok: false, message: \"GitHub connection failed: state mismatch. Please try connecting again.\" };\n  }\n\n  try {\n    const data = await apiFetch(\"/v1/actions\", {\n      method: \"POST\",\n      body: { action: \"github_oauth_callback\", code, redirect_uri: GITHUB_REDIRECT_URI },\n    });\n    localStorage.setItem(\"github_connected\", \"true\");\n    localStorage.setItem(\"github_username\", data.username || \"\");\n    return { ok: true, message: `GitHub connected${data.username ? ` as **@${data.username}**` : \"\"}.` };\n  } catch (err) {\n    const detail = err instanceof ApiError ? err.message : String(err);\n    return { ok: false, message: `Could not finish connecting GitHub (${detail}).` };\n  }\n}\n\n/**\n * Disconnecting GitHub also revokes the token stored server-side (SQLite),\n * via the \"disconnect_integration\" action \u2014 not just this browser's local\n * flag. Best-effort: local state is cleared even if the network call\n * fails, since the user's intent is \"stop using my GitHub identity\" either way.\n */\nexport async function disconnectGitHub() {\n  let warning = null;\n  try {\n    await apiFetch(\"/v1/actions\", {\n      method: \"POST\",\n      body: { action: \"disconnect_integration\", provider: \"github\" },\n    });\n  } catch (err) {\n    const detail = err instanceof ApiError ? err.message : String(err);\n    warning = `Could not confirm GitHub token removal on the server (${detail}). Cleared locally; if this keeps happening, revoke access from GitHub settings directly.`;\n  }\n\n  localStorage.removeItem(\"github_connected\");\n  localStorage.removeItem(\"github_username\");\n\n  return warning\n    ? { ok: false, message: warning }\n    : { ok: true, message: \"GitHub disconnected \\u2014 the stored server-side token was revoked.\" };\n}\n\n// ---------------------------------------------------------------------\n// GitLab\n// ---------------------------------------------------------------------\n\nexport function isGitLabConnected() {\n  return localStorage.getItem(\"gitlab_connected\") === \"true\";\n}\n\nexport function getGitLabAccessToken() {\n  return localStorage.getItem(\"gitlab_access_token\");\n}\n\nexport async function connectGitLab() {\n  const verifier = generateRandomToken();\n  sessionStorage.setItem(\"gitlab_pkce_verifier\", verifier);\n  const state = generateRandomToken();\n  sessionStorage.setItem(\"gitlab_oauth_state\", state);\n  const challenge = await generateCodeChallenge(verifier);\n\n  const params = new URLSearchParams({\n    client_id: GITLAB_CLIENT_ID,\n    redirect_uri: GITLAB_REDIRECT_URI,\n    response_type: \"code\",\n    scope: GITLAB_SCOPES,\n    state,\n    code_challenge: challenge,\n    code_challenge_method: \"S256\",\n  });\n  window.location.href = `${GITLAB_OAUTH_DOMAIN}/oauth/authorize?${params}`;\n}\n\n/** Call on GET /callback/gitlab. Exchanges the code directly with GitLab (no backend involved). */\nexport async function handleGitLabCallback() {\n  const url = new URL(window.location.href);\n  const code = url.searchParams.get(\"code\");\n  const state = url.searchParams.get(\"state\");\n  const expected = sessionStorage.getItem(\"gitlab_oauth_state\");\n  const verifier = sessionStorage.getItem(\"gitlab_pkce_verifier\");\n  sessionStorage.removeItem(\"gitlab_oauth_state\");\n  sessionStorage.removeItem(\"gitlab_pkce_verifier\");\n  window.history.replaceState({}, \"\", \"/\");\n\n  if (!code) return null;\n  if (!state || state !== expected) {\n    return { ok: false, message: \"GitLab connection failed: state mismatch. Please try connecting again.\" };\n  }\n\n  try {\n    const resp = await fetch(`${GITLAB_OAUTH_DOMAIN}/oauth/token`, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/x-www-form-urlencoded\" },\n      body: new URLSearchParams({\n        client_id: GITLAB_CLIENT_ID,\n        code,\n        grant_type: \"authorization_code\",\n        redirect_uri: GITLAB_REDIRECT_URI,\n        code_verifier: verifier,\n      }),\n    });\n    if (!resp.ok) throw new Error(`GitLab returned ${resp.status}`);\n    const tokens = await resp.json();\n    localStorage.setItem(\"gitlab_access_token\", tokens.access_token);\n    localStorage.setItem(\"gitlab_refresh_token\", tokens.refresh_token || \"\");\n    localStorage.setItem(\"gitlab_connected\", \"true\");\n    return { ok: true, message: \"GitLab connected.\" };\n  } catch (err) {\n    return { ok: false, message: `Could not finish connecting GitLab (${err.message}).` };\n  }\n}\n\n/** GitLab tokens are never sent to the backend, so disconnecting is purely local. */\nexport function disconnectGitLab() {\n  localStorage.removeItem(\"gitlab_connected\");\n  localStorage.removeItem(\"gitlab_access_token\");\n  localStorage.removeItem(\"gitlab_refresh_token\");\n  localStorage.removeItem(\"gitlab_username\");\n  return { ok: true, message: \"GitLab disconnected from this browser.\" };\n}\n",
  "js/stream.js": "// front-end/js/stream.js\n//\n// Parses the /v1/chat/completions response stream as it actually arrives\n// from the backend (see back-end/app/api/chat.py), instead of assuming a\n// single JSON document. The backend writes, in order and only as needed:\n//\n//   1. Zero or more newline-terminated {\"type\": \"progress\", ...} lines\n//      while waiting for the local vLLM server to become healthy\n//      (see app/services/backend_readiness_service.py).\n//   2. Either a single non-streamed {\"type\": \"error\" | \"confirmation_required\", ...}\n//      NDJSON line, and the response ends there; OR\n//   3. {\"type\": \"answer_start\"} followed by a newline, then a series of\n//      \"data: {\\\"token\\\": ...}\\n\\n\" SSE-style frames, ending in\n//      \"data: [DONE]\\n\\n\".\n//\n// This function dispatches each event to the matching handler as it\n// arrives, so the UI can render backend-readiness progress, human-in-the-\n// loop confirmations, and streamed tokens without waiting for the whole\n// response to finish.\n\n/**\n * @param {Response} response - a fetch() Response whose body is the stream.\n * @param {{\n *   onProgress?: (event: object) => void,\n *   onError?: (event: object) => void,\n *   onConfirmation?: (event: object) => void,\n *   onAnswerStart?: () => void,\n *   onToken?: (token: string) => void,\n *   onDone?: () => void,\n *   onFallback?: (event: object) => void,\n * }} handlers\n */\nexport async function consumeAgentStream(response, handlers) {\n  const reader = response.body.getReader();\n  const decoder = new TextDecoder();\n  let buffer = \"\";\n\n  const handleLine = (line) => {\n    const trimmed = line.trim();\n    if (!trimmed) return;\n\n    if (trimmed.startsWith(\"data: \")) {\n      const payload = trimmed.slice(6).trim();\n      if (payload === \"[DONE]\") {\n        handlers.onDone?.();\n        return;\n      }\n      try {\n        const parsed = JSON.parse(payload);\n        if (parsed.token) handlers.onToken?.(parsed.token);\n        if (parsed.type === \"error\") handlers.onError?.(parsed);\n      } catch {\n        // Ignore an unparseable/partial SSE chunk; more data may follow.\n      }\n      return;\n    }\n\n    let event;\n    try {\n      event = JSON.parse(trimmed);\n    } catch {\n      return;\n    }\n\n    switch (event.type) {\n      case \"progress\":\n        handlers.onProgress?.(event);\n        break;\n      case \"error\":\n        handlers.onError?.(event);\n        break;\n      case \"confirmation_required\":\n        handlers.onConfirmation?.(event);\n        break;\n      case \"answer_start\":\n        handlers.onAnswerStart?.();\n        break;\n      default:\n        handlers.onFallback?.(event);\n    }\n  };\n\n  while (true) {\n    const { done, value } = await reader.read();\n    if (done) break;\n\n    buffer += decoder.decode(value, { stream: true });\n    let newlineIndex;\n    while ((newlineIndex = buffer.indexOf(\"\\n\")) !== -1) {\n      handleLine(buffer.slice(0, newlineIndex));\n      buffer = buffer.slice(newlineIndex + 1);\n    }\n  }\n\n  if (buffer.trim()) handleLine(buffer);\n}\n",
  "js/theme.js": "// front-end/js/theme.js\n//\n// Dark/light theme toggle, persisted to localStorage with a system-\n// preference fallback on first load.\n\nexport function applyTheme(dark) {\n  document.documentElement.classList.toggle(\"dark\", dark);\n  const icon = document.getElementById(\"theme-icon\");\n  if (icon) icon.textContent = dark ? \"\\u2600\\uFE0F\" : \"\\uD83C\\uDF19\";\n  localStorage.setItem(\"theme\", dark ? \"dark\" : \"light\");\n}\n\nexport function toggleTheme() {\n  applyTheme(!document.documentElement.classList.contains(\"dark\"));\n}\n\nexport function initTheme() {\n  const saved = localStorage.getItem(\"theme\");\n  const prefersDark = window.matchMedia(\"(prefers-color-scheme: dark)\").matches;\n  applyTheme(saved ? saved === \"dark\" : prefersDark);\n}\n",
  "js/attachments.js": "// front-end/js/attachments.js\n//\n// File attachment handling: selection, size validation, drag & drop, and\n// the small \"chip\" UI showing files staged for the next message.\n\nconst MAX_FILE_BYTES = 2 * 1024 * 1024; // 2 MB per file; keep in sync with any reverse-proxy body-size limit.\n\nlet attachments = []; // [{ name, size, content }]\nlet onWarning = () => {};\n\nexport function initAttachments({ onWarning: warningHandler } = {}) {\n  if (warningHandler) onWarning = warningHandler;\n\n  const dropOverlay = document.getElementById(\"drop-overlay\");\n  let dragCounter = 0;\n\n  [\"dragenter\", \"dragover\"].forEach((evt) => {\n    document.body.addEventListener(evt, (e) => {\n      e.preventDefault();\n      dragCounter++;\n      dropOverlay?.classList.remove(\"hidden\");\n      dropOverlay?.classList.add(\"flex\");\n    });\n  });\n\n  [\"dragleave\", \"drop\"].forEach((evt) => {\n    document.body.addEventListener(evt, (e) => {\n      e.preventDefault();\n      dragCounter = Math.max(0, dragCounter - 1);\n      if (dragCounter === 0) {\n        dropOverlay?.classList.add(\"hidden\");\n        dropOverlay?.classList.remove(\"flex\");\n      }\n    });\n  });\n\n  document.body.addEventListener(\"drop\", (e) => {\n    if (e.dataTransfer?.files?.length) handleFileSelect(e.dataTransfer.files);\n  });\n}\n\nexport function getAttachments() {\n  return attachments;\n}\n\nexport function clearAttachments() {\n  attachments = [];\n  renderFileChips();\n}\n\nfunction formatBytes(bytes) {\n  if (bytes < 1024) return `${bytes} B`;\n  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;\n  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;\n}\n\nexport function renderFileChips() {\n  const box = document.getElementById(\"file-chips\");\n  if (!box) return;\n  box.innerHTML = \"\";\n  box.classList.toggle(\"hidden\", attachments.length === 0);\n\n  attachments.forEach((file, idx) => {\n    const chip = document.createElement(\"div\");\n    chip.className =\n      \"file-chip flex items-center gap-1.5 text-xs bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-full pl-3 pr-1.5 py-1\";\n\n    const label = document.createElement(\"span\");\n    label.className = \"max-w-[10rem] truncate\";\n    label.textContent = file.name;\n    chip.appendChild(label);\n\n    const size = document.createElement(\"span\");\n    size.className = \"text-slate-400\";\n    size.textContent = formatBytes(file.size);\n    chip.appendChild(size);\n\n    const removeBtn = document.createElement(\"button\");\n    removeBtn.className = \"h-5 w-5 rounded-full hover:bg-slate-200 dark:hover:bg-slate-700 flex items-center justify-center\";\n    removeBtn.innerHTML = \"&times;\";\n    removeBtn.onclick = () => {\n      attachments.splice(idx, 1);\n      renderFileChips();\n    };\n    chip.appendChild(removeBtn);\n\n    box.appendChild(chip);\n  });\n}\n\nfunction readFileAsText(file) {\n  return new Promise((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onload = () => resolve(reader.result);\n    reader.onerror = reject;\n    reader.readAsText(file);\n  });\n}\n\nexport async function handleFileSelect(fileList) {\n  for (const file of Array.from(fileList)) {\n    if (file.size > MAX_FILE_BYTES) {\n      onWarning(`Skipped **${file.name}** \\u2014 exceeds the ${formatBytes(MAX_FILE_BYTES)} limit.`);\n      continue;\n    }\n    try {\n      const content = await readFileAsText(file);\n      attachments.push({ name: file.name, size: file.size, content });\n    } catch {\n      onWarning(`Could not read **${file.name}** as text.`);\n    }\n  }\n\n  const fileInput = document.getElementById(\"file-input\");\n  if (fileInput) fileInput.value = \"\";\n  renderFileChips();\n}\n",
  "js/render.js": "// front-end/js/render.js\n//\n// DOM rendering helpers for chat bubbles, backend-readiness progress, and\n// human-in-the-loop confirmation cards. Pure presentation \u2014 no networking.\n\nfunction chatEl() {\n  return document.querySelector(\"#chat > div\");\n}\n\nexport function scrollToBottom() {\n  const chat = document.getElementById(\"chat\");\n  if (chat) chat.scrollTop = chat.scrollHeight;\n}\n\nfunction renderMarkdown(text) {\n  return window.marked.parse(text ?? \"\");\n}\n\nfunction highlightAll(container) {\n  container.querySelectorAll(\"pre code\").forEach((block) => window.hljs.highlightElement(block));\n}\n\nexport function appendMessage(role, text, files = []) {\n  document.getElementById(\"empty-state\")?.remove();\n\n  const wrap = document.createElement(\"div\");\n  wrap.className = `msg-enter flex items-start gap-3 ${role === \"user\" ? \"justify-end\" : \"justify-start\"}`;\n\n  const bubble = document.createElement(\"div\");\n\n  if (role === \"user\") {\n    bubble.className =\n      \"max-w-[85%] sm:max-w-[75%] rounded-2xl rounded-tr-sm bg-brand-600 text-white px-4 py-2.5 text-sm sm:text-base whitespace-pre-wrap break-words\";\n    bubble.textContent = text;\n\n    if (files.length) {\n      const fileRow = document.createElement(\"div\");\n      fileRow.className = \"flex flex-wrap gap-1.5 mt-2\";\n      files.forEach((f) => {\n        const tag = document.createElement(\"span\");\n        tag.className = \"text-[11px] bg-white/15 rounded-full px-2 py-0.5\";\n        tag.textContent = `\\uD83D\\uDCC4 ${f.name}`;\n        fileRow.appendChild(tag);\n      });\n      bubble.appendChild(fileRow);\n    }\n  } else {\n    const avatar = document.createElement(\"div\");\n    avatar.className =\n      \"h-8 w-8 shrink-0 rounded-full bg-brand-100 dark:bg-brand-900 text-brand-700 dark:text-brand-200 flex items-center justify-center text-sm font-semibold\";\n    avatar.textContent = \"\\uD83E\\uDD16\";\n    wrap.appendChild(avatar);\n\n    bubble.className =\n      \"prose-chat max-w-[85%] sm:max-w-[75%] rounded-2xl rounded-tl-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 px-4 py-2.5 text-sm sm:text-base prose prose-sm dark:prose-invert prose-p:my-1.5 prose-pre:my-2\";\n    bubble.innerHTML = renderMarkdown(text);\n    highlightAll(bubble);\n  }\n\n  wrap.appendChild(bubble);\n  chatEl().appendChild(wrap);\n  scrollToBottom();\n  return bubble;\n}\n\nexport function updateAssistantBubble(bubble, fullText) {\n  bubble.innerHTML = renderMarkdown(fullText);\n  highlightAll(bubble);\n  scrollToBottom();\n}\n\nfunction formatProgressText(message, percent) {\n  return `${message ?? \"Working...\"}${typeof percent === \"number\" ? ` (${percent}%)` : \"\"}`;\n}\n\nexport function appendProgressMessage(message, percent) {\n  document.getElementById(\"empty-state\")?.remove();\n\n  const wrap = document.createElement(\"div\");\n  wrap.className = \"msg-enter flex items-start gap-3 justify-start\";\n\n  const avatar = document.createElement(\"div\");\n  avatar.className =\n    \"h-8 w-8 shrink-0 rounded-full bg-brand-100 dark:bg-brand-900 text-brand-700 dark:text-brand-200 flex items-center justify-center text-sm font-semibold\";\n  avatar.textContent = \"\\u23F3\";\n  wrap.appendChild(avatar);\n\n  const bubble = document.createElement(\"div\");\n  bubble.className =\n    \"rounded-2xl rounded-tl-sm bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 px-4 py-2.5 text-sm text-slate-600 dark:text-slate-300\";\n  bubble.dataset.progressText = \"true\";\n  bubble.textContent = formatProgressText(message, percent);\n  wrap.appendChild(bubble);\n\n  chatEl().appendChild(wrap);\n  scrollToBottom();\n  return wrap;\n}\n\nexport function updateProgressMessage(wrapEl, message, percent) {\n  if (!wrapEl) return;\n  const bubble = wrapEl.querySelector(\"[data-progress-text]\");\n  if (bubble) bubble.textContent = formatProgressText(message, percent);\n  scrollToBottom();\n}\n\nexport function removeProgressMessage(wrapEl) {\n  wrapEl?.remove();\n}\n\n/**\n * Renders an inline Approve/Deny card for a risky tool call the backend is\n * asking the human to confirm (write_file, run_shell, or any github_ or\n * gitlab_ prefixed repo-management tool -- see RISKY_TOOLS in\n * back-end/app/api/chat.py). onResolve(decision) is invoked with\n * \"approve\" or \"deny\" when a button is clicked.\n */\nexport function appendConfirmation(toolName, args, onResolve) {\n  document.getElementById(\"empty-state\")?.remove();\n\n  const wrap = document.createElement(\"div\");\n  wrap.className = \"msg-enter flex items-start gap-3 justify-start\";\n\n  const avatar = document.createElement(\"div\");\n  avatar.className =\n    \"h-8 w-8 shrink-0 rounded-full bg-amber-100 dark:bg-amber-900 text-amber-700 dark:text-amber-200 flex items-center justify-center text-sm font-semibold\";\n  avatar.textContent = \"\\u26A0\\uFE0F\";\n  wrap.appendChild(avatar);\n\n  const card = document.createElement(\"div\");\n  card.className =\n    \"max-w-[85%] sm:max-w-[75%] rounded-2xl rounded-tl-sm bg-white dark:bg-slate-800 border border-amber-300 dark:border-amber-700 px-4 py-3 text-sm\";\n\n  const title = document.createElement(\"p\");\n  title.className = \"font-medium mb-1\";\n  title.textContent = `Approve ${toolName}?`;\n  card.appendChild(title);\n\n  const pre = document.createElement(\"pre\");\n  pre.className = \"bg-slate-100 dark:bg-slate-900 rounded-lg p-2 text-xs overflow-x-auto mb-3\";\n  pre.textContent = JSON.stringify(args, null, 2);\n  card.appendChild(pre);\n\n  const btnRow = document.createElement(\"div\");\n  btnRow.className = \"flex gap-2\";\n\n  const approveBtn = document.createElement(\"button\");\n  approveBtn.className = \"text-xs px-3 py-1.5 rounded-full bg-emerald-600 text-white hover:bg-emerald-700 transition\";\n  approveBtn.textContent = \"Approve\";\n\n  const denyBtn = document.createElement(\"button\");\n  denyBtn.className =\n    \"text-xs px-3 py-1.5 rounded-full bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600 transition\";\n  denyBtn.textContent = \"Deny\";\n\n  const resolve = async (decision) => {\n    approveBtn.disabled = true;\n    denyBtn.disabled = true;\n    approveBtn.classList.add(\"opacity-50\");\n    denyBtn.classList.add(\"opacity-50\");\n    await onResolve(decision);\n  };\n  approveBtn.onclick = () => resolve(\"approve\");\n  denyBtn.onclick = () => resolve(\"deny\");\n\n  btnRow.appendChild(approveBtn);\n  btnRow.appendChild(denyBtn);\n  card.appendChild(btnRow);\n\n  wrap.appendChild(card);\n  chatEl().appendChild(wrap);\n  scrollToBottom();\n}\n",
  "js/chat.js": "// front-end/js/chat.js\n//\n// Chat send/receive logic against POST /v1/chat/completions (see\n// back-end/app/api/chat.py) and POST /v1/actions for resolving\n// human-in-the-loop confirmations (see\n// back-end/app/services/pending_actions_service.py).\n\nimport { apiFetch, apiStream, ApiError } from \"./api.js\";\nimport { consumeAgentStream } from \"./stream.js\";\nimport { getAttachments, clearAttachments, renderFileChips } from \"./attachments.js\";\nimport { getGitLabAccessToken } from \"./integrations.js\";\nimport {\n  appendMessage,\n  updateAssistantBubble,\n  appendProgressMessage,\n  updateProgressMessage,\n  removeProgressMessage,\n  appendConfirmation,\n  scrollToBottom,\n} from \"./render.js\";\n\nlet history = [];\n\nfunction setLoading(loading) {\n  const sendBtn = document.getElementById(\"send-btn\");\n  const inputEl = document.getElementById(\"input\");\n  const typingIndicator = document.getElementById(\"typing-indicator\");\n  if (sendBtn) sendBtn.disabled = loading;\n  if (inputEl) inputEl.disabled = loading;\n  typingIndicator?.classList.toggle(\"hidden\", !loading);\n}\n\n/**\n * Resolves a pending human-in-the-loop action created by the backend. For\n * gitlab_* tools, attaches this browser's locally-stored GitLab token for\n * this one call only (see integrations.js) -- it is never persisted\n * server-side. This is a plain, non-streaming JSON call (POST /v1/actions\n * always returns a single flat object immediately), unlike send() below.\n */\nasync function resolvePendingAction(actionId, decision, toolName) {\n  setLoading(true);\n  try {\n    const isGitlabTool = toolName && toolName.startsWith(\"gitlab_\");\n    const result = await apiFetch(\"/v1/actions\", {\n      method: \"POST\",\n      body: {\n        action: \"action_pending\",\n        action_id: actionId,\n        decision,\n        gitlab_token: isGitlabTool ? getGitLabAccessToken() : null,\n      },\n    });\n    appendMessage(\"assistant\", result.result ?? \"No response from agent.\");\n  } catch (err) {\n    const detail = err instanceof ApiError ? err.message : String(err);\n    appendMessage(\"assistant\", `Could not resolve that action: ${detail}`);\n  } finally {\n    setLoading(false);\n  }\n}\n\nexport async function send() {\n  const inputEl = document.getElementById(\"input\");\n  const message = inputEl.value.trim();\n  const attachments = getAttachments();\n  if (!message && attachments.length === 0) return;\n\n  const filesForRequest = attachments.map(({ name, content }) => ({ name, content }));\n  const filesForDisplay = attachments.map(({ name, size }) => ({ name, size }));\n\n  history.push({ role: \"user\", content: message, attachments: filesForRequest });\n  appendMessage(\"user\", message || \"(sent files only)\", filesForDisplay);\n\n  inputEl.value = \"\";\n  inputEl.style.height = \"auto\";\n  clearAttachments();\n  renderFileChips();\n  setLoading(true);\n\n  let progressWrap = null;\n  let answerBubble = null;\n  let answerText = \"\";\n  let handledTerminalEvent = false;\n\n  try {\n    const response = await apiStream(\"/v1/chat/completions\", {\n      message,\n      history: history.slice(0, -1),\n      attachments: filesForRequest,\n    });\n\n    await consumeAgentStream(response, {\n      onProgress: (event) => {\n        if (!progressWrap) {\n          progressWrap = appendProgressMessage(event.message, event.percent);\n        } else {\n          updateProgressMessage(progressWrap, event.message, event.percent);\n        }\n      },\n      onError: (event) => {\n        removeProgressMessage(progressWrap);\n        appendMessage(\"assistant\", event.message ?? \"The agent hit an error.\");\n        handledTerminalEvent = true;\n      },\n      onConfirmation: (event) => {\n        removeProgressMessage(progressWrap);\n        appendConfirmation(event.tool_name, event.args, (decision) =>\n          resolvePendingAction(event.action_id, decision, event.tool_name)\n        );\n        handledTerminalEvent = true;\n      },\n      onAnswerStart: () => {\n        removeProgressMessage(progressWrap);\n        answerBubble = appendMessage(\"assistant\", \"\");\n      },\n      onToken: (token) => {\n        answerText += token;\n        if (answerBubble) {\n          updateAssistantBubble(answerBubble, answerText);\n        }\n      },\n      onFallback: (event) => {\n        // Defensive: a flat {result|error} object with no \"type\" is not\n        // currently emitted by the backend, but handled here for\n        // forward/backward compatibility with older response shapes.\n        removeProgressMessage(progressWrap);\n        const reply = event.result ?? event.error ?? \"No response from agent.\";\n        appendMessage(\"assistant\", reply);\n        history.push({ role: \"assistant\", content: reply });\n        handledTerminalEvent = true;\n      },\n    });\n\n    if (answerBubble) {\n      history.push({ role: \"assistant\", content: answerText });\n    } else if (!handledTerminalEvent) {\n      removeProgressMessage(progressWrap);\n      appendMessage(\"assistant\", \"No response from agent.\");\n    }\n  } catch (err) {\n    removeProgressMessage(progressWrap);\n    const detail = err instanceof ApiError ? err.message : err.message || String(err);\n    appendMessage(\"assistant\", `Request failed: ${detail}`);\n  } finally {\n    setLoading(false);\n    inputEl.focus();\n  }\n}\n\nexport function resetHistory() {\n  history = [];\n}\n\nexport function autoResizeInput(el) {\n  el.style.height = \"auto\";\n  el.style.height = Math.min(el.scrollHeight, 160) + \"px\";\n}\n\nexport function handleInputKeydown(e) {\n  if (e.key === \"Enter\" && !e.shiftKey) {\n    e.preventDefault();\n    send();\n  }\n}\n\nexport { scrollToBottom };\n",
  "js/auth-ui.js": "// front-end/js/auth-ui.js\n//\n// DOM wiring for the signed-in/signed-out header state. Separate from\n// auth.js (which only knows about network/session state) so presentation\n// logic doesn't leak into the API layer.\n\nimport { isSignedIn, getCachedUser, loginWithGoogle, logout } from \"./auth.js\";\nimport { resetHistory } from \"./chat.js\";\n\nexport function refreshAuthUI() {\n  const signedIn = isSignedIn();\n  document.getElementById(\"auth-signed-out\")?.classList.toggle(\"hidden\", signedIn);\n  document.getElementById(\"auth-signed-in\")?.classList.toggle(\"hidden\", !signedIn);\n  document.getElementById(\"auth-signed-in\")?.classList.toggle(\"flex\", signedIn);\n\n  if (signedIn) {\n    const user = getCachedUser();\n    const emailEl = document.getElementById(\"user-email\");\n    if (emailEl) emailEl.textContent = user?.email ?? \"\";\n  }\n}\n\nexport async function handleLogout() {\n  await logout();\n  resetHistory();\n  refreshAuthUI();\n  window.location.href = \"/\";\n}\n\nexport function wireAuthButtons() {\n  document.getElementById(\"google-login-btn\")?.addEventListener(\"click\", loginWithGoogle);\n  document.getElementById(\"logout-btn\")?.addEventListener(\"click\", handleLogout);\n}\n",
  "js/integrations-ui.js": "// front-end/js/integrations-ui.js\n//\n// DOM wiring for the GitHub/GitLab integrations modal and the header-level\n// quick-connect buttons. Delegates all network/state logic to\n// integrations.js and only handles rendering + event binding here.\n\nimport {\n  isGitHubConnected,\n  getGitHubUsername,\n  connectGitHub,\n  disconnectGitHub,\n  isGitLabConnected,\n  connectGitLab,\n  disconnectGitLab,\n} from \"./integrations.js\";\nimport { appendMessage } from \"./render.js\";\n\nexport function openIntegrationsModal() {\n  const modal = document.getElementById(\"integrations-modal\");\n  modal?.classList.remove(\"hidden\");\n  modal?.classList.add(\"flex\");\n  refreshIntegrationsUI();\n}\n\nexport function closeIntegrationsModal() {\n  const modal = document.getElementById(\"integrations-modal\");\n  modal?.classList.add(\"hidden\");\n  modal?.classList.remove(\"flex\");\n}\n\nasync function onGitHubToggle() {\n  const result = isGitHubConnected() ? await disconnectGitHub() : connectGitHub();\n  if (result?.message) appendMessage(\"assistant\", result.message);\n  refreshIntegrationsUI();\n}\n\nasync function onGitLabToggle() {\n  const result = isGitLabConnected() ? disconnectGitLab() : await connectGitLab();\n  if (result?.message) appendMessage(\"assistant\", result.message);\n  refreshIntegrationsUI();\n}\n\nexport function refreshIntegrationsUI() {\n  const githubConnected = isGitHubConnected();\n  const githubUsername = getGitHubUsername();\n\n  const githubStatus = document.getElementById(\"github-status-text\");\n  if (githubStatus) {\n    githubStatus.textContent = githubConnected ? `Connected${githubUsername ? \" as @\" + githubUsername : \"\"}` : \"Not connected\";\n  }\n  const githubBtn = document.getElementById(\"github-connect-btn\");\n  if (githubBtn) {\n    githubBtn.textContent = githubConnected ? \"Disconnect\" : \"Connect\";\n    githubBtn.onclick = onGitHubToggle;\n  }\n\n  const gitlabConnected = isGitLabConnected();\n  const gitlabStatus = document.getElementById(\"gitlab-status-text\");\n  if (gitlabStatus) {\n    gitlabStatus.textContent = gitlabConnected ? \"Connected\" : \"Not connected\";\n  }\n  const gitlabBtn = document.getElementById(\"gitlab-connect-btn\");\n  if (gitlabBtn) {\n    gitlabBtn.textContent = gitlabConnected ? \"Disconnect\" : \"Connect\";\n    gitlabBtn.onclick = onGitLabToggle;\n  }\n\n  document.getElementById(\"integrations-dot\")?.classList.toggle(\"hidden\", !(githubConnected || gitlabConnected));\n\n  const githubAuthBtn = document.getElementById(\"github-auth-btn\");\n  const githubAuthLabel = document.getElementById(\"github-auth-btn-label\");\n  if (githubAuthLabel) {\n    githubAuthLabel.textContent = githubConnected ? `GitHub \\u2713${githubUsername ? \" @\" + githubUsername : \"\"}` : \"Connect GitHub\";\n  }\n  if (githubAuthBtn) {\n    githubAuthBtn.onclick = onGitHubToggle;\n    githubAuthBtn.classList.toggle(\"opacity-70\", githubConnected);\n  }\n\n  const gitlabAuthBtn = document.getElementById(\"gitlab-auth-btn\");\n  const gitlabAuthLabel = document.getElementById(\"gitlab-auth-btn-label\");\n  if (gitlabAuthLabel) {\n    gitlabAuthLabel.textContent = gitlabConnected ? \"GitLab \\u2713\" : \"Connect GitLab\";\n  }\n  if (gitlabAuthBtn) {\n    gitlabAuthBtn.onclick = onGitLabToggle;\n    gitlabAuthBtn.classList.toggle(\"opacity-70\", gitlabConnected);\n  }\n}\n\nexport function wireIntegrationsButtons() {\n  document.getElementById(\"integrations-open-btn\")?.addEventListener(\"click\", openIntegrationsModal);\n  document.getElementById(\"integrations-close-btn\")?.addEventListener(\"click\", closeIntegrationsModal);\n}\n",
  "js/main.js": "// front-end/js/main.js\n//\n// Application bootstrap. Wires DOM events to the feature modules and\n// dispatches on the current pathname for the two OAuth redirect targets\n// this SPA handles client-side: \"/callback/github\", \"/callback/gitlab\".\n// (Google's own callback is handled entirely server-side -- see auth.js.)\n\nimport { completeLoginFromUrlFragment, refreshCurrentUser } from \"./auth.js\";\nimport { refreshAuthUI, wireAuthButtons } from \"./auth-ui.js\";\nimport { handleGitHubCallback, handleGitLabCallback } from \"./integrations.js\";\nimport { refreshIntegrationsUI, wireIntegrationsButtons } from \"./integrations-ui.js\";\nimport { initTheme, toggleTheme } from \"./theme.js\";\nimport { initAttachments, handleFileSelect } from \"./attachments.js\";\nimport { appendMessage } from \"./render.js\";\nimport { send, autoResizeInput, handleInputKeydown } from \"./chat.js\";\n\nfunction wireChatInput() {\n  const inputEl = document.getElementById(\"input\");\n  const sendBtn = document.getElementById(\"send-btn\");\n  const fileInput = document.getElementById(\"file-input\");\n\n  inputEl?.addEventListener(\"input\", () => autoResizeInput(inputEl));\n  inputEl?.addEventListener(\"keydown\", handleInputKeydown);\n  sendBtn?.addEventListener(\"click\", send);\n  fileInput?.addEventListener(\"change\", (e) => handleFileSelect(e.target.files));\n}\n\nasync function dispatchOnRoute() {\n  const path = window.location.pathname;\n\n  if (path === \"/callback/github\") {\n    const result = await handleGitHubCallback();\n    if (result?.message) appendMessage(\"assistant\", result.message);\n    return;\n  }\n\n  if (path === \"/callback/gitlab\") {\n    const result = await handleGitLabCallback();\n    if (result?.message) appendMessage(\"assistant\", result.message);\n    return;\n  }\n\n  // Google's OAuth callback is server-side; on success it redirects the\n  // browser back here with \"#token=...\" in the URL fragment (see auth.js).\n  await completeLoginFromUrlFragment();\n}\n\nwindow.addEventListener(\"DOMContentLoaded\", async () => {\n  initTheme();\n  document.getElementById(\"theme-toggle-btn\")?.addEventListener(\"click\", toggleTheme);\n\n  wireAuthButtons();\n  wireIntegrationsButtons();\n  wireChatInput();\n  initAttachments({ onWarning: (message) => appendMessage(\"assistant\", message) });\n\n  await dispatchOnRoute();\n  await refreshCurrentUser();\n\n  refreshAuthUI();\n  refreshIntegrationsUI();\n  document.getElementById(\"input\")?.focus();\n});\n",
  "Dockerfile": "# front-end/Dockerfile\n#\n# Serves the static SPA with nginx. Two changes from the previous version:\n#   1. Listens on , not 3000 -- nginx:alpine's default vhost already\n#      binds 80; overriding EXPOSE alone never changed the actual listen\n#      port, so the old image silently served on 80 regardless of EXPOSE.\n#      This version ships its own server block that actually listens on\n#      the documented port.\n#   2. Adds an SPA fallback (try_files ... /index.html) so client-side\n#      routes like /callback/github and /callback/gitlab, which this app\n#      handles in main.js via window.location.pathname, don't 404 on a\n#      hard refresh or direct link.\nFROM nginx:1.27-alpine\n\nCOPY nginx.conf /etc/nginx/conf.d/default.conf\nCOPY . /usr/share/nginx/html\n\nEXPOSE \n\nHEALTHCHECK --interval=30s --timeout=3s --start-period=5s \\\n  CMD wget -qO- http://localhost:/ >/dev/null 2>&1 || exit 1\n",
  "nginx.conf": "# front-end/nginx.conf\n#\n# Static SPA server block. try_files falls back to /index.html so\n# client-side-only routes (/callback/github, /callback/gitlab) resolve\n# correctly instead of 404ing on a direct navigation or page refresh.\nserver {\n    listen ;\n    server_name _;\n    root /usr/share/nginx/html;\n    index index.html;\n\n    location / {\n        try_files $uri $uri/ /index.html;\n    }\n\n    # ES modules must be served with a JS MIME type for <script type=\"module\">.\n    location ~* \\.js$ {\n        add_header Content-Type application/javascript;\n    }\n\n    add_header X-Content-Type-Options nosniff;\n    add_header X-Frame-Options DENY;\n    add_header Referrer-Policy strict-origin-when-cross-origin;\n}\n"
}


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Scaffold the front-end/ SPA project.")
    parser.add_argument(
        "target_dir", nargs="?", default=".",
        help="Parent directory in which to create front-end/ (default: current directory).",
    )
    parser.add_argument(
        "--force", action="store_true",
        help="Overwrite files that already exist instead of skipping them.",
    )
    return parser.parse_args()


def write_project(base_dir: Path, force: bool) -> tuple[int, int]:
    root = base_dir / "local"
    written = 0
    skipped = 0

    for relative_path, content in FILES.items():
        full_path = root / relative_path
        full_path.parent.mkdir(parents=True, exist_ok=True)

        if full_path.exists() and not force:
            print(f"skip   {full_path.relative_to(base_dir)} (already exists, use --force to overwrite)")
            skipped += 1
            continue

        full_path.write_text(content, encoding="utf-8")
        print(f"create {full_path.relative_to(base_dir)}")
        written += 1

    return written, skipped


def main() -> None:
    args = parse_args()
    base_dir = Path(args.target_dir).resolve()
    base_dir.mkdir(parents=True, exist_ok=True)

    written, skipped = write_project(base_dir, args.force)

    print()
    print(f"Done. {written} file(s) written, {skipped} skipped.")
    print(f"Project root: {base_dir / 'front-end'}")
    print()
    print("Next steps:")
    print("  1. Ensure front-end/index.html includes:")
    print('       <script type="module" src="/config.js"></script>')
    print('       <script type="module" src="/js/main.js"></script>')
    print("  2. Fill in front-end/config.js (BACKEND_URL, OAuth client IDs) or")
    print("     substitute its placeholders at deploy/container-build time.")
    print("  3. docker build -t coding-agent-frontend front-end/")
    print("     docker run -p : coding-agent-frontend")


if __name__ == "__main__":
    main()
